        nodes.push_back({v, 0.0, 0, -1, -1});
        return nodes.size() - 1;
    }

    int add(int a, int b) {
        double val = nodes[a].value + nodes[b].value;
        nodes.push_back({val, 0.0, 1, a, b});
        return nodes.size() - 1;
